#include <cctype>
#include <optional>
#include <string>
#include <utility>
#include <vector>

using Headers = std::vector<std::pair<std::string, std::string>>;
struct Request { std::string method, target, version; Headers headers; std::string body; bool keepAlive; };

namespace detail
{
    inline std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }
    inline std::string trim(const std::string& v)
    {
        const std::size_t s{ v.find_first_not_of(" \t") }, e{ v.find_last_not_of(" \t") };
        return s == std::string::npos ? "" : v.substr(s, e - s + 1);
    }
    inline std::vector<std::string> values(const Headers& h, const std::string& name)
    {
        std::vector<std::string> out;
        for (const auto& [n, v] : h) if (n == name) out.push_back(v);
        return out;
    }
    inline bool hasToken(const Headers& h, const std::string& name, const std::string& token)
    {
        for (const std::string& v : values(h, name))
        {
            std::size_t start{ 0 };
            while (start <= v.size())
            {
                const std::size_t comma{ v.find(',', start) };
                if (lower(trim(v.substr(start, comma == std::string::npos ? std::string::npos : comma - start))) == token) return true;
                if (comma == std::string::npos) break;
                start = comma + 1;
            }
        }
        return false;
    }
}

class RequestParser
{
public:
    RequestParser(std::size_t maxHead, std::size_t maxBody) : maxHead{ maxHead }, maxBody{ maxBody } {}

    void feed(const std::string& bytes) { if (!status) buffer += bytes; }

    std::optional<Request> next()
    {
        if (status) return std::nullopt;
        const std::size_t end{ buffer.find("\r\n\r\n") };
        if (end == std::string::npos) { if (buffer.size() > maxHead) fail(431); return std::nullopt; }
        if (end > maxHead) { fail(431); return std::nullopt; }
        Request r;
        if (!parseHead(buffer.substr(0, end), r)) { fail(400); return std::nullopt; }
        std::size_t at{ end + 4 };
        const auto te{ detail::values(r.headers, "transfer-encoding") };
        const auto cl{ detail::values(r.headers, "content-length") };
        if (!te.empty() && !cl.empty()) { fail(400); return std::nullopt; }
        if (!te.empty())
        {
            if (te.size() != 1 || detail::lower(te[0]) != "chunked") { fail(400); return std::nullopt; }
            const int result{ decodeChunked(at, r.body) };
            if (result < 0) return std::nullopt;
            if (result > 0) { fail(result); return std::nullopt; }
        }
        else if (!cl.empty())
        {
            for (const std::string& v : cl) if (v != cl[0]) { fail(400); return std::nullopt; }
            if (cl[0].empty() || cl[0].size() > 15) { fail(400); return std::nullopt; }
            for (char c : cl[0]) if (!std::isdigit(static_cast<unsigned char>(c))) { fail(400); return std::nullopt; }
            const std::size_t length{ static_cast<std::size_t>(std::stoull(cl[0])) };
            if (length > maxBody) { fail(413); return std::nullopt; }
            if (buffer.size() - at < length) return std::nullopt;
            r.body = buffer.substr(at, length);
            at += length;
        }
        r.keepAlive = r.version == "HTTP/1.1" ? !detail::hasToken(r.headers, "connection", "close")
                                              : detail::hasToken(r.headers, "connection", "keep-alive");
        buffer.erase(0, at);
        return r;
    }

    bool failed() const { return status != 0; }
    int errorStatus() const { return status; }
    std::size_t pending() const { return buffer.size(); }

private:
    std::size_t maxHead, maxBody;
    std::string buffer;
    int status{ 0 };

    void fail(int code) { status = code; buffer.clear(); }

    static bool parseHead(const std::string& head, Request& r)
    {
        std::vector<std::string> lines;
        std::size_t at{ 0 };
        while (true)
        {
            const std::size_t e{ head.find("\r\n", at) };
            lines.push_back(head.substr(at, e == std::string::npos ? std::string::npos : e - at));
            if (e == std::string::npos) break;
            at = e + 2;
        }
        const std::string& first{ lines[0] };
        const std::size_t a{ first.find(' ') };
        const std::size_t b{ a == std::string::npos ? a : first.find(' ', a + 1) };
        if (a == std::string::npos || b == std::string::npos || first.find(' ', b + 1) != std::string::npos) return false;
        r.method = first.substr(0, a);
        r.target = first.substr(a + 1, b - a - 1);
        r.version = first.substr(b + 1);
        if (r.method.empty() || r.target.empty() || (r.version != "HTTP/1.1" && r.version != "HTTP/1.0")) return false;
        for (std::size_t i{ 1 }; i < lines.size(); ++i)
        {
            const std::size_t colon{ lines[i].find(':') };
            if (colon == std::string::npos || colon == 0) return false;
            const std::string name{ lines[i].substr(0, colon) };
            if (name.find_first_of(" \t") != std::string::npos) return false;
            r.headers.push_back({ detail::lower(name), detail::trim(lines[i].substr(colon + 1)) });
        }
        return true;
    }

    // -1: need more bytes. 0: done (at moved past the body). Otherwise: the failure status.
    int decodeChunked(std::size_t& at, std::string& body) const
    {
        std::size_t pos{ at };
        std::string out;
        for (;;)
        {
            const std::size_t lineEnd{ buffer.find("\r\n", pos) };
            if (lineEnd == std::string::npos) return buffer.size() - pos > 1024 ? 400 : -1;
            std::string sizeText{ buffer.substr(pos, lineEnd - pos) };
            if (const std::size_t semi{ sizeText.find(';') }; semi != std::string::npos) sizeText.erase(semi);
            if (sizeText.empty() || sizeText.size() > 8) return 400;
            for (char c : sizeText) if (!std::isxdigit(static_cast<unsigned char>(c))) return 400;
            const std::size_t size{ static_cast<std::size_t>(std::stoul(sizeText, nullptr, 16)) };
            pos = lineEnd + 2;
            if (size == 0)
            {
                for (;;)
                {
                    const std::size_t e{ buffer.find("\r\n", pos) };
                    if (e == std::string::npos) return -1;
                    const bool empty{ e == pos };
                    pos = e + 2;
                    if (empty) break;
                }
                body = out;
                at = pos;
                return 0;
            }
            if (out.size() + size > maxBody) return 413;
            if (buffer.size() - pos < size + 2) return -1;
            if (buffer.compare(pos + size, 2, "\r\n") != 0) return 400;
            out.append(buffer, pos, size);
            pos += size + 2;
        }
    }
};

std::string buildResponse(int status, const Headers& headers, const std::string& body)
{
    std::string reason;
    switch (status)
    {
    case 200: reason = "OK"; break;
    case 201: reason = "Created"; break;
    case 204: reason = "No Content"; break;
    case 301: reason = "Moved Permanently"; break;
    case 302: reason = "Found"; break;
    case 304: reason = "Not Modified"; break;
    case 400: reason = "Bad Request"; break;
    case 401: reason = "Unauthorized"; break;
    case 403: reason = "Forbidden"; break;
    case 404: reason = "Not Found"; break;
    case 405: reason = "Method Not Allowed"; break;
    case 429: reason = "Too Many Requests"; break;
    case 500: reason = "Internal Server Error"; break;
    case 503: reason = "Service Unavailable"; break;
    default: reason = "Unknown"; break;
    }
    std::string out{ "HTTP/1.1 " + std::to_string(status) + " " + reason + "\r\n" };
    for (const auto& [name, value] : headers) out += name + ": " + value + "\r\n";
    const bool noBody{ status < 200 || status == 204 || status == 304 };
    if (!noBody) out += "Content-Length: " + std::to_string(body.size()) + "\r\n";
    out += "\r\n";
    if (!noBody) out += body;
    return out;
}

unitTests:
static const std::string PIPELINE{
    "GET /a HTTP/1.1
Host: x

"
    "POST /api HTTP/1.1
Host: x
Content-Length: 5

hello"
    "POST /up HTTP/1.1
Host: x
Transfer-Encoding: chunked

4
Wiki
6;note=1
pedia 
D
in

chunks.
0
X-Trailer: t

"
    "GET /b HTTP/1.0
Connection: Keep-Alive

" };

static std::vector<Request> all(RequestParser& p) { std::vector<Request> out; while (auto r{ p.next() }) out.push_back(*r); return out; }

TEST("pipelined requests at once") {
    RequestParser p{ 8192, 1 << 20 };
    p.feed(PIPELINE);
    const auto rs{ all(p) };
    CHECK_EQ(rs.size(), 4u);
    if (rs.size() != 4) return;
    CHECK_EQ(rs[0].target, std::string("/a")); CHECK(rs[0].keepAlive);
    CHECK_EQ(rs[1].body, std::string("hello"));
    CHECK_EQ(rs[2].body, std::string("Wikipedia in

chunks."));
    CHECK_EQ(rs[3].version, std::string("HTTP/1.0")); CHECK(rs[3].keepAlive);
    CHECK_EQ(p.pending(), 0u);
}
TEST("the same bytes, one at a time") {
    RequestParser p{ 8192, 1 << 20 };
    std::vector<Request> rs;
    for (char c : PIPELINE) { p.feed(std::string(1, c)); while (auto r{ p.next() }) rs.push_back(*r); }
    CHECK_EQ(rs.size(), 4u);
    if (rs.size() == 4) CHECK_EQ(rs[2].body, std::string("Wikipedia in

chunks."));
    CHECK(!p.failed());
}
TEST("keep-alive rules") {
    RequestParser p{ 8192, 1024 };
    p.feed("GET / HTTP/1.1
Connection: Upgrade, Close

GET / HTTP/1.0

");
    const auto rs{ all(p) };
    CHECK_EQ(rs.size(), 2u);
    if (rs.size() == 2) { CHECK(!rs[0].keepAlive); CHECK(!rs[1].keepAlive); }
}
TEST("errors and limits") {
    RequestParser bad{ 8192, 1024 };
    bad.feed("GET / HTTP/2.0

");
    CHECK(!bad.next().has_value()); CHECK_EQ(bad.errorStatus(), 400);
    bad.feed("GET / HTTP/1.1

");
    CHECK(!bad.next().has_value());
    RequestParser smuggle{ 8192, 1024 };
    smuggle.feed("POST / HTTP/1.1
Content-Length: 3
Transfer-Encoding: chunked

");
    CHECK(!smuggle.next().has_value()); CHECK_EQ(smuggle.errorStatus(), 400);
    RequestParser big{ 8192, 10 };
    big.feed("POST / HTTP/1.1
Content-Length: 11

");
    CHECK(!big.next().has_value()); CHECK_EQ(big.errorStatus(), 413);
    RequestParser bigChunks{ 8192, 10 };
    bigChunks.feed("POST / HTTP/1.1
Transfer-Encoding: chunked

8
12345678
8
");
    CHECK(!bigChunks.next().has_value()); CHECK_EQ(bigChunks.errorStatus(), 413);
    RequestParser longHead{ 64, 1024 };
    longHead.feed("GET / HTTP/1.1
X-Long: " + std::string(100, 'a'));
    CHECK(!longHead.next().has_value()); CHECK_EQ(longHead.errorStatus(), 431);
    RequestParser badChunk{ 8192, 1024 };
    badChunk.feed("POST / HTTP/1.1
Transfer-Encoding: chunked

ZZ
");
    CHECK(!badChunk.next().has_value()); CHECK_EQ(badChunk.errorStatus(), 400);
    RequestParser waiting{ 8192, 1024 };
    waiting.feed("POST / HTTP/1.1
Content-Length: 5

hel");
    CHECK(!waiting.next().has_value()); CHECK(!waiting.failed());
}
TEST("building responses") {
    CHECK_EQ(buildResponse(200, { { "Content-Type", "text/plain" } }, "hi"), std::string("HTTP/1.1 200 OK
Content-Type: text/plain
Content-Length: 2

hi"));
    CHECK_EQ(buildResponse(204, {}, "ignored"), std::string("HTTP/1.1 204 No Content

"));
    CHECK_EQ(buildResponse(404, {}, ""), std::string("HTTP/1.1 404 Not Found
Content-Length: 0

"));
}

